// Parsear respuesta de Ollama
const ollamaData = $input.first().json;
const responseText = ollamaData.response;

let analisis;

try {
  // Limpiar markdown si existe
  let clean = responseText
    .replace(/```json/g, '')
    .replace(/```/g, '')
    .trim();

  // Extraer JSON
  const match = clean.match(/\{[\s\S]*\}/);
  if (match) {
    analisis = JSON.parse(match[0]);
  } else {
    analisis = JSON.parse(clean);
  }

  // Validar estructura mínima
  if (!analisis.puntuacion) {
    throw new Error('JSON sin puntuacion');
  }

} catch (error) {
  console.error('Error parseando:', error);
  // Fallback
  analisis = {
    puntuacion: 5,
    aspectos_positivos: ["Código recibido correctamente"],
    errores: ["No se pudo analizar automáticamente"],
    sugerencias: ["Revisar manualmente"],
    comentario: "Error técnico en análisis automático"
  };
}

// Obtener datos previos
const datosEstudiante = $('🔍 Extraer').first().json;

// Resultado final
return {
  json: {
    // Datos estudiante
    nombre: datosEstudiante.nombre,
    email: datosEstudiante.email,
    ejercicio: datosEstudiante.ejercicio,
    codigo: datosEstudiante.codigo,

    // Análisis IA
    puntuacion: analisis.puntuacion,
    aspectos_positivos: analisis.aspectos_positivos || [],
    errores: analisis.errores || [],
    sugerencias: analisis.sugerencias || [],
    comentario: analisis.comentario || "",

    // Campos calculados
    fecha: new Date().toISOString(),
    aprobado: analisis.puntuacion >= 5,
    estado: analisis.puntuacion >= 5 ? "APROBADO" : "SUSPENDIDO"
  }
};
